<template>
    <div class="detailRecord">
      <title-line :title="title" />
      <div class="record-list">
        <div v-for="item,index in recordList" :key="index" class="item">
            <div class="left">
                <div class="packet-icon"></div>
                <div class="medium">
                    <div class="name">{{item.name}}</div>
                    <div class="time">{{item.time}}</div>
                </div>
            </div>
            <div class="mons">{{item.mons}}</div>
        </div>
      </div>
    </div>
</template>
<script>
import TitleLine from './TitleLine'
import { vipagent } from '@/api/user'
export default {
    components: {
        TitleLine
    },
    data() {
        return {
        title: '红包详情',
        recordList: [
        //     {
        //     name:'桃花一朵朵',
        //     time:'2月5日 20:37:56',
        //     mons:'10.82'
        // }
    ]
        }
    },
    created() {
        this.onLoad()
    },
    methods: {
        async onLoad() {
            const formData = new FormData()
            formData.append('hongbaoid',this.$route.query.id)
            fetch(process.env.VUE_APP_BASE_API + '/hongbao/gethbrecords', {
                method: 'POST',
                body: formData
            }).then(res => res.json())
            .then(async(data) => {
                if (data.status == '1') {
                    this.recordList = data.recordlist.map(item => {
                        return {
                            name: item.uname,
                            time: item.usetimeDesc,
                            mons: item.moneysDesc
                        }
                    })
                }else {
                    this.$toast(data.msg)
                }  
            })
        
        }
    }
}
</script>
<style lang="scss" scoped>
.detailRecord {
    min-height: 100vh;
    width: 100%;
    background: var(--inner-bg-color);
    background-size: 100% 100%;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
    .record-list{
        margin: 20px 40px;
        .item{
            display: flex;
            flex-wrap: wrap;
            justify-content: space-between;
            height: 112px;
            border-bottom-color:rgba(255,255,255,0.20); 
            border-bottom-width: 1px;
            border-bottom-style: solid;
            .left{
                display: flex;
                justify-content: left;
                align-items: center;
            }
            .packet-icon{
                width: 64px;
                height: 64px;
                background: url('~@/assets/rodPocket/红包.png') no-repeat center;
                background-size: 100%;
                margin: 24px 16px 24px 0;
             }
            .medium{
                display: flex;
                flex-direction: column;
                justify-content: space-between;
                .name{
                    font-family: PingFangSC-Medium;
                    font-size: 28px;
                    color: #FFFFFF;
                    letter-spacing: 0;
                    font-weight: 500;
                 }
                .time{
                    font-family: PingFangSC-Regular;
                    font-size: 24px;
                    color: rgb(255, 255, 255, 0.6);
                    letter-spacing: 0;
                    font-weight: 400;
                    margin-top: 8px;
                 }
             }
            .mons{
                font-family: HelveticaNeue-Bold;
                font-size: 32px;
                color: #FFCF50;
                letter-spacing: 0;
                text-align: right;
                line-height: 20px;
                font-weight: 700;
                line-height: 112px;
            }
        }
    }
}
</style>
  
  